@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h2 class="mb-3">Project Board</h2>

@if (_loading)
{
    <div class="d-flex justify-content-center my-5">
        <div class="spinner-border" role="status">
            <span class="visually-hidden">Loading…</span>
        </div>
    </div>
}
else if (_error is not null)
{
    <div class="alert alert-danger d-flex align-items-center" role="alert">
        <span class="me-2">⚠️</span>
        <span>@_error</span>
        <button class="btn btn-sm btn-outline-danger ms-auto" @onclick="LoadTasksAsync">Retry</button>
    </div>
}
else
{
    <!-- Stats bar -->
    <div class="row g-2 mb-3">
        <div class="col">
            <div class="stats-card bg-light rounded p-2 text-center">
                <div class="fw-bold fs-5">@_allTasks.Count</div>
                <small class="text-muted">Total</small>
            </div>
        </div>
        <div class="col">
            <div class="stats-card bg-light rounded p-2 text-center">
                <div class="fw-bold fs-5">@GetColumnTasks("To Do").Count</div>
                <small class="text-muted">To Do</small>
            </div>
        </div>
        <div class="col">
            <div class="stats-card bg-light rounded p-2 text-center">
                <div class="fw-bold fs-5">@GetColumnTasks("In Progress").Count</div>
                <small class="text-muted">In Progress</small>
            </div>
        </div>
        <div class="col">
            <div class="stats-card bg-light rounded p-2 text-center">
                <div class="fw-bold fs-5">@GetColumnTasks("Done").Count</div>
                <small class="text-muted">Done</small>
            </div>
        </div>
        <div class="col">
            <div class="stats-card bg-light rounded p-2 text-center">
                <div class="fw-bold fs-5 text-danger">@_allTasks.Count(t => t.DueDate < DateTime.Today)</div>
                <small class="text-muted">Overdue</small>
            </div>
        </div>
    </div>

    <!-- Search bar -->
    <div class="mb-3">
        <input type="text"
               class="form-control"
               placeholder="Search tasks by title…"
               @bind="_searchTerm"
               @bind:event="oninput" />
    </div>

    <!-- Kanban columns -->
    <div class="row g-3 kanban-row">
        @foreach (var column in _columns)
        {
            var tasks = GetFilteredColumnTasks(column);
            <div class="col-md-4">
                <div class="kanban-column rounded">
                    <div class="kanban-column-header d-flex justify-content-between align-items-center p-3">
                        <h5 class="mb-0">@column</h5>
                        <span class="badge bg-secondary rounded-pill">@tasks.Count</span>
                    </div>

                    <div class="kanban-column-body p-2">
                        @foreach (var task in tasks)
                        {
                            <div class="card task-card mb-2">
                                <div class="card-body p-2">
                                    <div class="d-flex justify-content-between align-items-start mb-1">
                                        <strong class="card-title mb-0">@task.Title</strong>
                                        <span class="badge priority-@task.Priority.ToLowerInvariant()">@task.Priority</span>
                                    </div>
                                    <div class="text-muted small mb-2">
                                        <span>👤 @task.Assignee</span>
                                        <span class="ms-2">📅 @task.DueDate.ToString("MMM dd")</span>
                                    </div>
                                    <div class="d-flex gap-1">
                                        @if (column != _columns[0])
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    disabled="@_movingTaskId.HasValue"
                                                    @onclick="() => MoveTaskAsync(task, -1)">
                                                ◀ Move Left
                                            </button>
                                        }
                                        @if (column != _columns[^1])
                                        {
                                            <button class="btn btn-outline-secondary btn-sm"
                                                    disabled="@_movingTaskId.HasValue"
                                                    @onclick="() => MoveTaskAsync(task, 1)">
                                                Move Right ▶
                                            </button>
                                        }
                                    </div>
                                </div>
                            </div>
                        }

                        @if (_addingToColumn == column)
                        {
                            <div class="card border-primary mb-2">
                                <div class="card-body p-2">
                                    <div class="mb-2">
                                        <input type="text" class="form-control form-control-sm" placeholder="Title"
                                               @bind="_newTitle" />
                                    </div>
                                    <div class="mb-2">
                                        <input type="text" class="form-control form-control-sm" placeholder="Assignee"
                                               @bind="_newAssignee" />
                                    </div>
                                    <div class="mb-2">
                                        <select class="form-select form-select-sm" @bind="_newPriority">
                                            <option value="High">High</option>
                                            <option value="Medium">Medium</option>
                                            <option value="Low">Low</option>
                                        </select>
                                    </div>
                                    <div class="mb-2">
                                        <input type="date" class="form-control form-control-sm"
                                               @bind="_newDueDate" />
                                    </div>
                                    <div class="d-flex gap-1">
                                        <button class="btn btn-primary btn-sm" disabled="@_saving" @onclick="SaveNewTaskAsync">
                                            @if (_saving) { <span class="spinner-border spinner-border-sm me-1"></span> }
                                            Save
                                        </button>
                                        <button class="btn btn-outline-secondary btn-sm" disabled="@_saving" @onclick="CancelAdd">
                                            Cancel
                                        </button>
                                    </div>
                                </div>
                            </div>
                        }
                    </div>

                    <div class="p-2">
                        <button class="btn btn-outline-primary btn-sm w-100"
                                disabled="@(_addingToColumn is not null)"
                                @onclick="() => BeginAdd(column)">
                            + Add Task
                        </button>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private readonly string[] _columns = ["To Do", "In Progress", "Done"];

    private List<TaskItem> _allTasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchTerm = string.Empty;

    // Move state
    private int? _movingTaskId;

    // Add-task form state
    private string? _addingToColumn;
    private string _newTitle = string.Empty;
    private string _newAssignee = string.Empty;
    private string _newPriority = "Medium";
    private DateTime _newDueDate = DateTime.Today.AddDays(7);
    private bool _saving;

    protected override async Task OnInitializedAsync()
    {
        await LoadTasksAsync();
    }

    private async Task LoadTasksAsync()
    {
        _loading = true;
        _error = null;

        try
        {
            _allTasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private List<TaskItem> GetColumnTasks(string status)
        => _allTasks.Where(t => t.Status == status).ToList();

    private List<TaskItem> GetFilteredColumnTasks(string status)
    {
        var tasks = GetColumnTasks(status);
        if (!string.IsNullOrWhiteSpace(_searchTerm))
        {
            tasks = tasks.Where(t => t.Title.Contains(_searchTerm, StringComparison.OrdinalIgnoreCase)).ToList();
        }
        return tasks;
    }

    private async Task MoveTaskAsync(TaskItem task, int direction)
    {
        var currentIndex = Array.IndexOf(_columns, task.Status);
        var newIndex = currentIndex + direction;
        if (newIndex < 0 || newIndex >= _columns.Length) return;

        _movingTaskId = task.Id;
        try
        {
            var newStatus = _columns[newIndex];
            await TaskService.UpdateTaskStatusAsync(task.Id, newStatus);
            // Update local state
            _allTasks = _allTasks.Select(t => t.Id == task.Id ? t with { Status = newStatus } : t).ToList();
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
        finally
        {
            _movingTaskId = null;
        }
    }

    private void BeginAdd(string column)
    {
        _addingToColumn = column;
        _newTitle = string.Empty;
        _newAssignee = string.Empty;
        _newPriority = "Medium";
        _newDueDate = DateTime.Today.AddDays(7);
    }

    private void CancelAdd()
    {
        _addingToColumn = null;
    }

    private async Task SaveNewTaskAsync()
    {
        if (string.IsNullOrWhiteSpace(_newTitle) || _addingToColumn is null) return;

        _saving = true;
        try
        {
            var created = await TaskService.CreateTaskAsync(_newTitle, _newAssignee, _newPriority, _newDueDate);
            // CreateTaskAsync returns a task with default status; ensure it has the target column status
            if (created.Status != _addingToColumn)
            {
                await TaskService.UpdateTaskStatusAsync(created.Id, _addingToColumn);
                created = created with { Status = _addingToColumn };
            }
            _allTasks.Add(created);
            _addingToColumn = null;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
        finally
        {
            _saving = false;
        }
    }
}

.kanban-row {
    min-height: 60vh;
}

.kanban-column {
    background-color: #f0f2f5;
    display: flex;
    flex-direction: column;
    height: 100%;
}

.kanban-column-header {
    border-bottom: 2px solid #dee2e6;
}

.kanban-column-body {
    flex: 1;
    overflow-y: auto;
}

.task-card {
    transition: box-shadow 0.15s ease;
}

.task-card:hover {
    box-shadow: 0 2px 8px rgba(0, 0, 0, 0.12);
}

.stats-card {
    border: 1px solid #dee2e6;
}

::deep .priority-high {
    background-color: #dc3545;
    color: #fff;
}

::deep .priority-medium {
    background-color: #ffc107;
    color: #212529;
}

::deep .priority-low {
    background-color: #198754;
    color: #fff;
}

