+                                        @if (column != _columns[0])
+                                        {
+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    disabled="@_movingTaskId.HasValue"
+                                                    @onclick="() => MoveTaskAsync(task, -1)">
+                                                ◀ Move Left
+                                            </button>
+                                        }
+                                        @if (column != _columns[^1])
+                                        {
+                                            <button class="btn btn-outline-secondary btn-sm"
+                                                    disabled="@_movingTaskId.HasValue"
+                                                    @onclick="() => MoveTaskAsync(task, 1)">
+                                                Move Right ▶
+                                            </button>
+                                        }
+                                    </div>
+                                </div>
+                            </div>
+                        }
