+                                            Save
+                                        </button>
+                                        <button class="btn btn-outline-secondary btn-sm" disabled="@_saving" @onclick="CancelAdd">
+                                            Cancel
+                                        </button>
+                                    </div>
+                                </div>
+                            </div>
+                        }
+                    </div>
